import { Component, OnInit } from '@angular/core';
import { JobService } from 'src/app/service/job/job.service';
import { Job } from '../../models/job';
import { Company } from 'src/app/landing/models/company';
import { CompanyService } from 'src/app/service/company/company.service';

@Component({
  selector: 'app-landing',
  templateUrl: './landing.component.html',
  styleUrls: ['./landing.component.css']
})
export class LandingComponent implements OnInit {

  constructor(
    private jobService: JobService,
    private compService: CompanyService
  ) {}

  jobs: Job[] = [];
  companies: Company[] = [];

  ngOnInit() {
    this.getAllJobs();
    this.getAllCompanies();
  }

  getAllJobs() {
    this.jobService.getAllJobs().subscribe((res) => {
      this.jobs = res;
    });
  }

  getAllCompanies() {
    this.compService.getAllCompanies().subscribe((res) => {
      this.companies = res;
    });
  }
}
<div class="page">
<app-header variant="guest"></app-header>

<section class="hero">
  <div class="wrap">
    <h1>Find work that fits.<br>Hire people who fit.</h1>
    <p class="lead">One portal for job seekers and companies — post a role, apply in minutes, track every application in one place.</p>
    <div class="search-row">
      <input type="text" placeholder="Job title, skill or keyword">
      <a routerLink="/job/all-jobs" class="btn btn-primary">Search jobs</a>
      <a routerLink="/auth/register/company" class="btn btn-ghost-dark">Post a job</a>
    </div>
    <div class="tag-row">
      <span class="tag-pill">React</span><span class="tag-pill">Java</span>
      <span class="tag-pill">Product</span><span class="tag-pill">Data</span>
      <span class="tag-pill">Sales</span><span class="tag-pill">Design</span>
    </div>
    <div class="stat-row">
      <div><div class="stat-num">{{jobs.length}}</div><div class="stat-label">Open roles</div></div>
      <div><div class="stat-num">{{companies.length}}</div><div class="stat-label">Companies</div></div>
    </div>
  </div>
</section>

<section class="section-pad">
  <div class="wrap">
    <div class="section-head">
      <h2>Featured roles</h2>
      <a routerLink="/job/all-jobs" class="mono-label">View all jobs &rarr;</a>
    </div>
    <div class="card-row">
      <div class="job-card" *ngFor="let job of jobs | slice:0:2">
        <div class="top">
          <h3>{{ job.jobTitle }}</h3>
          <span class="chip chip-open" *ngIf="job.active">Open</span>
        </div>
        <div class="meta">
          {{ job.companyName }} &middot; {{ job.location }} &middot; {{ job.salary }}
        </div>
        <div class="skill-tags">
          <span class="skill-tag" *ngFor="let skill of job.skills">{{ skill }}</span>
        </div>
      </div>
    </div>
  </div>
</section>

<app-footer></app-footer>
</div>
